#requires -Version 5.1
param([Parameter(Mandatory=$true)][ValidateSet('install','remove')][string]$Action,[Parameter(Mandatory=$true)][string]$Root,[Parameter(Mandatory=$true)][string]$Data)
$ErrorActionPreference='Stop'
function Full([string]$p){
 if(!$p -or $p -notmatch '^[A-Za-z]:[\\/]'){throw 'An absolute local path is required'}
 [IO.Path]::GetFullPath($p).TrimEnd('\')
}
function Plain([string]$p){
 $p=Full $p
 while($p){
  if(Test-Path -LiteralPath $p){
   if((Get-Item -LiteralPath $p -Force).Attributes -band [IO.FileAttributes]::ReparsePoint){throw ('Refusing reparse point: '+$p)}
  }
  $parent=Split-Path -Parent $p
  if($parent -eq $p){break}
  $p=$parent
 }
}
$Root=Full $Root
$Data=Full $Data
$package=Split-Path -Parent $Root
$pikoHome=Split-Path -Parent (Split-Path -Parent $package)
$image=Join-Path $Root 'Lertaro.Service.exe'
Plain $Root
if((Full $PSScriptRoot) -ine $Root){throw 'The service script must run from its real version directory'}
function Version([string]$dir){
 $dir=Full $dir
 if((Split-Path -Parent $dir) -ine $package -or (Split-Path -Leaf $dir) -ieq 'current'){throw 'Version is outside this Piko package'}
 Plain $dir
}
function ReadInstall([string]$dir){
 Version $dir
 $file=Join-Path $dir '.piko-install.json'
 Plain $file
 $r=Get-Content -LiteralPath $file -Raw|ConvertFrom-Json
 if($r.name -cne 'lertaro' -or $r.kind -cne 'portable' -or $r.verified -ne $true -or !$r.id -or !$r.key -or !$r.version -or !$r.source.identity -or $r.checksum -notmatch '^[a-fA-F0-9]{64}$' -or $r.manifestHash -notmatch '^[a-fA-F0-9]{64}$'){throw 'Invalid Piko Lertaro installation receipt'}
 if([IO.Path]::IsPathRooted($r.dir) -or $r.dir -match '(^|[\\/])\.\.([\\/]|$)' -or (Full (Join-Path $pikoHome $r.dir)) -ine (Full $dir)){throw 'Installation receipt path mismatch'}
 $r
}
$install=ReadInstall $Root
$folder=if($install.layout -eq 'named-v1'){'lertaro'}else{$install.key}
if($package -ine (Full (Join-Path (Join-Path $pikoHome 'apps') $folder))){throw 'Unexpected Lertaro package layout'}
$expectedData=Full (Join-Path (Join-Path (Join-Path $pikoHome 'persist') $folder) '.piko-system')
if($Data -ine $expectedData){throw 'Persistent receipt directory belongs to another package'}
Plain $Data
$null=[IO.Directory]::CreateDirectory($Data)
$journal=Join-Path $Data 'piko-lertaro-service.json'
Plain $journal
function Proof([string]$dir,$r){
 if($r.key -cne $install.key -or $r.source.identity -cne $install.source.identity){throw 'Installation belongs to another package source'}
 [pscustomobject]@{root=(Full $dir);id=$r.id;key=$r.key;identity=$r.source.identity;checksum=$r.checksum;manifestHash=$r.manifestHash}
}
$currentProof=Proof $Root $install
function ValidateProof($p){
 if(!$p -or !$p.id -or $p.key -cne $install.key -or $p.identity -cne $install.source.identity -or $p.checksum -notmatch '^[a-fA-F0-9]{64}$' -or $p.manifestHash -notmatch '^[a-fA-F0-9]{64}$'){throw 'Foreign or invalid saved installation identity'}
 Version $p.root
 if(Test-Path -LiteralPath $p.root){
  $r=ReadInstall $p.root
  $actual=Proof $p.root $r
  if(($actual.id -cne $p.id -or $actual.checksum -cne $p.checksum -or $actual.manifestHash -cne $p.manifestHash) -and $p.root -ine $Root){throw 'Installation no longer matches its service receipt'}
 }
}
function Tree([string]$p){
 Plain $p
 if(!(Test-Path -LiteralPath $p -PathType Container)){throw ('Missing data directory: '+$p)}
 $stack=New-Object 'Collections.Generic.Stack[string]'
 $stack.Push($p)
 while($stack.Count){
  $parent=$stack.Pop()
  foreach($item in Get-ChildItem -LiteralPath $parent -Force){
   if($item.Attributes -band [IO.FileAttributes]::ReparsePoint){throw ('Refusing a link inside Data: '+$item.FullName)}
   if($item.PSIsContainer){$stack.Push($item.FullName)}
  }
 }
}
function SourceData([string]$dir){
 Version $dir
 $path=Join-Path $dir 'Data'
 if(!(Test-Path -LiteralPath $path)){return $null}
 $item=Get-Item -LiteralPath $path -Force
 if($item.Attributes -band [IO.FileAttributes]::ReparsePoint){
  $legacy=Full (Join-Path (Split-Path -Parent $Data) 'Data')
  if(@($item.Target).Count -ne 1 -or (Full ([string]$item.Target)) -ine $legacy){throw 'Data link belongs to an external installation'}
  $path=$legacy
 }
 Tree $path
 $path
}
function Registration{Get-CimInstance Win32_Service -Filter "Name='LertaroService'"}
function Owner($s){
 if($s.Name -cne 'LertaroService'){throw 'Unexpected service name'}
 if($s.PathName -match '^"([^"\r\n]+)"\s+--service$'){$exe=$Matches[1]}
 elseif($s.PathName -match '^([^\s"\r\n]+)\s+--service$'){$exe=$Matches[1]}
 else{throw 'Ambiguous or unrecognized service command line; refusing takeover'}
 if($exe -match '%|(^|[\\/])\.\.([\\/]|$)'){throw 'Ambiguous service image'}
 $exe=Full $exe
 if((Split-Path -Leaf $exe) -ine 'Lertaro.Service.exe'){throw 'External service executable'}
 $dir=Split-Path -Parent $exe
 if($dir -ieq (Join-Path $package 'current')){
  $link=Get-Item -LiteralPath $dir -Force
  if(!($link.Attributes -band [IO.FileAttributes]::ReparsePoint) -or @($link.Target).Count -ne 1){throw 'Cannot prove legacy current service ownership'}
  $target=[string]$link.Target
  if(![IO.Path]::IsPathRooted($target)){$target=Join-Path $package $target}
  $dir=Full $target
 }
 Version $dir
 if(Test-Path -LiteralPath $dir){return (Proof $dir (ReadInstall $dir))}
 if($record -and $record.active.root -ieq $dir){ValidateProof $record.active;return $record.active}
 throw 'Service version receipt and Data are missing; ownership and historical data cannot be recovered'
}
function Control{
 param([Parameter(ValueFromRemainingArguments=$true)][string[]]$arguments)
 $s=Registration
 if($s){$null=Owner $s}
 $message=& sc.exe @arguments 2>&1
 if($LASTEXITCODE -ne 0){throw ('sc.exe failed ('+$LASTEXITCODE+'): '+($message|Out-String))}
}
function AwaitState([string]$state){
 $deadline=(Get-Date).AddSeconds(60)
 do{
  $s=Registration
  if($state -eq 'absent' -and !$s){return}
  if($s -and $s.State -eq $state){$null=Owner $s;return}
  Start-Sleep -Milliseconds 250
 }while((Get-Date) -lt $deadline)
 throw ('LertaroService did not reach '+$state)
}
function CloseCheck([string]$dir){
 foreach($p in Get-CimInstance Win32_Process -Filter "Name='Lertaro.App.exe' OR Name='lff.exe'"){
  if(!$p.ExecutablePath){throw 'Close Lertaro and lff: process ownership cannot be verified'}
  $processDir=Split-Path -Parent (Full $p.ExecutablePath)
  if($processDir -ieq $dir -or $processDir -ieq (Join-Path $package 'current')){throw 'Close Lertaro and lff before migrating Data'}
 }
}
function StopOwned{
 $s=Registration
 if($s){$owner=Owner $s;CloseCheck $owner.root;if($s.State -ne 'Stopped'){Control -arguments @('stop','LertaroService');AwaitState 'Stopped'}}
}
function Save{
 $tmp=Join-Path $Data ('receipt-'+[guid]::NewGuid().ToString('N')+'.tmp')
 $record.updated=(Get-Date).ToUniversalTime().ToString('o')
 [IO.File]::WriteAllText($tmp,($record|ConvertTo-Json -Depth 8),(New-Object Text.UTF8Encoding($false)))
 if(Test-Path -LiteralPath $journal){[IO.File]::Replace($tmp,$journal,[NullString]::Value)}else{[IO.File]::Move($tmp,$journal)}
}
function CopyData([string]$source,[string]$destination){
 Tree $source
 Plain $destination
 $null=[IO.Directory]::CreateDirectory($destination)
 $message=& robocopy.exe $source $destination /E /COPYALL /DCOPY:DAT /B /XJ /R:1 /W:1 2>&1
 if($LASTEXITCODE -lt 0 -or $LASTEXITCODE -ge 8){throw ('Data copy failed ('+$LASTEXITCODE+'): '+($message|Out-String))}
 Tree $destination
}
function Backup($proof){
 ValidateProof $proof
 CloseCheck $proof.root
 $source=SourceData $proof.root
 if(!$source){throw ('Previous Data is missing at '+$proof.root+'; lossless recovery needs a complete backup')}
 $generation='backup-'+[guid]::NewGuid().ToString('N')
 $record.pending=[pscustomobject]@{kind='backup';path=$generation;proof=$proof}
 Save
 CopyData $source (Join-Path $Data $generation)
 $record.backups=@($record.backups)+@([pscustomobject]@{proof=$proof;generation=$generation})
 $record.pending=$null
 Save
 Join-Path $Data $generation
}
function LastBackup([string]$dir){
 $entry=@($record.backups|Where-Object {$_.proof.root -ieq $dir}|Select-Object -Last 1)
 if($entry.Count){Join-Path $Data $entry[0].generation}else{$null}
}
# Keep privileged repair state outside the vendor installation and serialize it.
$acl=New-Object Security.AccessControl.DirectorySecurity
$acl.SetAccessRuleProtection($true,$false)
foreach($sid in @('S-1-5-18','S-1-5-32-544')){
 $identity=New-Object Security.Principal.SecurityIdentifier($sid)
 $rule=New-Object Security.AccessControl.FileSystemAccessRule($identity,'FullControl','ContainerInherit,ObjectInherit','None','Allow')
 $acl.AddAccessRule($rule)
}
$acl.SetOwner((New-Object Security.Principal.SecurityIdentifier('S-1-5-32-544')))
Set-Acl -LiteralPath $Data -AclObject $acl
$lockPath=Join-Path $Data 'lertaro.lock'
Plain $lockPath
$lock=[IO.File]::Open($lockPath,[IO.FileMode]::OpenOrCreate,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None)
$record=$null
$trusted=$false
try{
 if(Test-Path -LiteralPath $journal){
  $record=Get-Content -LiteralPath $journal -Raw|ConvertFrom-Json
  if($record.schemaVersion -ne 3 -or $record.packageRoot -ine $package -or $record.key -cne $install.key -or $record.identity -cne $install.source.identity -or $record.service -cne 'LertaroService' -or $record.fresh -isnot [bool] -or $record.backups -isnot [array]){throw 'Unsupported or foreign Lertaro service receipt; preserve it for recovery'}
  ValidateProof $record.active
  foreach($backup in $record.backups){
   ValidateProof $backup.proof
   if($backup.generation -notmatch '^backup-[a-f0-9]{32}$'){throw 'Invalid backup generation in receipt'}
   Tree (Join-Path $Data $backup.generation)
  }
 }
 $registration=Registration
 $registeredOwner=if($registration){Owner $registration}else{$null}
 if($record -and $registeredOwner -and $registeredOwner.root -ine $record.active.root){throw 'Service registration and receipt ownership disagree'}
 if(!$record){
  $active=if($registeredOwner){$registeredOwner}else{$currentProof}
  $record=[pscustomobject]@{schemaVersion=3;packageRoot=$package;key=$install.key;identity=$install.source.identity;service='LertaroService';active=$active;fresh=(!$registeredOwner);backups=@();phase='adopted';pending=$null;error='';updated=''}
 }
 $trusted=$true
 # Only a completed copy may be finalized after an interrupted rename/receipt update.
 if($record.pending -and $record.pending.kind -eq 'restore-complete'){
  ValidateProof $record.pending.proof
  $stage=Full $record.pending.path
  $pendingRoot=$record.pending.proof.root
  if((Split-Path -Parent $stage) -ine $pendingRoot -or (Split-Path -Leaf $stage) -notmatch '^\.piko-restore-[a-f0-9]{32}$'){throw 'Invalid pending restore path'}
  $destination=Join-Path $pendingRoot 'Data'
  if(Test-Path -LiteralPath $stage){Tree $stage;if(Test-Path -LiteralPath $destination){throw 'Pending restore conflicts with Data; both copies were preserved'};[IO.Directory]::Move($stage,$destination)}else{Tree $destination}
  $record.active=$record.pending.proof
  $record.phase='restored'
  $record.pending=$null
 }
 Save
 if($Action -eq 'remove'){
  # Removing an unselected candidate never changes another version's service.
  $candidate=$record.active.root -ine $Root
  if(!$candidate){StopOwned}
  CloseCheck $Root
  $source=SourceData $Root
  if($source){$null=Backup $currentProof}
  elseif(!$candidate -and !$record.fresh -and !(LastBackup $Root)){throw 'Active Data is missing and no complete backup exists; cannot claim safe removal'}
  if(!$candidate){
   if(Registration){Control -arguments @('delete','LertaroService');AwaitState 'absent'}
   $record.phase='removed'
  }
  $record.error=''
  Save
  Write-Output 'Removed owned integration or candidate; retained Data generations and receipt'
  return
 }
 if(!(Test-Path -LiteralPath $image -PathType Leaf)){throw ('Missing service executable: '+$image)}
 Plain $image
 StopOwned
 CloseCheck $Root
 $previous=$record.active
 $source=SourceData $previous.root
 $target=Join-Path $Root 'Data'
 $linked=$false
 if(Test-Path -LiteralPath $target){$linked=[bool]((Get-Item -LiteralPath $target -Force).Attributes -band [IO.FileAttributes]::ReparsePoint);if($linked){$null=SourceData $Root}}
 $backup=LastBackup $previous.root
 $restore=($previous.root -ine $Root -or $linked -or !$source) -and !($record.phase -eq 'removed' -and $previous.root -ieq $Root -and $source -and !$linked)
 if($restore){
  if($source -and $record.phase -ne 'removed'){$backup=Backup $previous;$record.fresh=$false}
  if(!$backup -and (!$record.fresh -or $registeredOwner)){throw ('Previous Data is missing at '+$previous.root+' and no complete backup exists; historical data cannot be recovered')}
  if(!$backup){
   $legacy=Join-Path (Split-Path -Parent $Data) 'Data'
   if(Test-Path -LiteralPath $legacy){throw 'Untracked historical persistent Data exists; reconcile it before starting empty'}
   foreach($candidate in Get-ChildItem -LiteralPath $package -Directory -Force){
    if($candidate.Name -ne 'current' -and $candidate.FullName -ine $Root -and (Test-Path -LiteralPath (Join-Path $candidate.FullName 'Data'))){throw 'Untracked version Data exists; refusing to silently start empty'}
   }
  }
  if(Test-Path -LiteralPath $target){
   if($linked){[IO.Directory]::Delete($target)}else{Tree $target;if(@(Get-ChildItem -LiteralPath $target -Force).Count){throw ('Data conflict at '+$target+'; both Data and backups were preserved')};[IO.Directory]::Delete($target)}
  }
  if(Registration){Control -arguments @('delete','LertaroService');AwaitState 'absent'}
  $stage=Join-Path $Root ('.piko-restore-'+[guid]::NewGuid().ToString('N'))
  $record.pending=[pscustomobject]@{kind='restore-copying';path=$stage;proof=$currentProof}
  Save
  if($backup){CopyData $backup $stage}else{$null=[IO.Directory]::CreateDirectory($stage)}
  $record.pending.kind='restore-complete'
  Save
  [IO.Directory]::Move($stage,$target)
  $record.active=$currentProof
  $record.phase='restored'
  $record.pending=$null
  Save
 }
 if(Registration){Control -arguments @('delete','LertaroService');AwaitState 'absent'}
 $record.active=$currentProof
 $record.phase='registering'
 $record.fresh=$false
 $record.error=''
 Save
 $quoted=[string]::Format('{0}{1}{0} --service',[char]34,$image)
 $null=New-Service -Name 'LertaroService' -DisplayName 'Lertaro Background Service' -BinaryPathName $quoted -StartupType Automatic
 Control -arguments @('config','LertaroService','start=','delayed-auto')
 Control -arguments @('failure','LertaroService','reset=','86400','actions=','restart/15000/restart/30000/restart/60000')
 Control -arguments @('start','LertaroService')
 AwaitState 'Running'
 $running=Registration
 if((Owner $running).root -ine $Root -or $running.PathName -ine $quoted){throw 'Running service does not use the approved real version path'}
 $record.phase='installed'
 Save
 Write-Output ('Installed Lertaro service at '+$image)
}catch{
 if($trusted){$record.error=$_.Exception.Message;Save}
 throw
}finally{$lock.Dispose()}
